<?php
 use App\Services\HMVC\HMVC; if (!function_exists('hmvc')) { function hmvc(string $target, array $parameters = []) { return HMVC::run($target, $parameters); } } if (!function_exists('module_view')) { function module_view(string $view, array $data = [], array $mergeData = []) { return view($view, $data, $mergeData); } } if (!function_exists('template_render')) { function template_render(string $view, array $data = [], bool $return = false) { return app(\App\Libraries\Template::class)->render($view, $data, $return); } } if (!function_exists('holiday_theme')) { function holiday_theme() { return \App\Services\Theme\HolidayThemeService::getActiveTheme(); } } 